import test from 'node:test';
import assert from 'node:assert/strict';
import {BUNDLE_FIELDS,BUNDLE_MAX_OUTPUT_TOKENS,bundleJsonSchema,formatClinicalBundlePrompt,validateClinicalBundle} from '../netlify/lib/ai-note.mjs';
const data={hipoteses:'HIPÓTESE DE ENTORSE, A CONFIRMAR',tratamento:'AVALIAR MEDIDAS CONSERVADORAS E SINAIS DE ALERTA',evolucao:'QUEIXA: DOR EM JOELHO\nHDA: TRAUMA ONTEM\nEXAME FÍSICO: DOR À PALPAÇÃO\nCONDUTA: ORIENTAÇÃO INFORMADA',laudo:'LAUDO: DOR EM JOELHO, REVISAR',fisioterapia:'CONSIDERAR AVALIAÇÃO PARA FISIOTERAPIA',medicacao:'ANALGESIA A AVALIAR, SEM PRESCREVER',afastamento:'AVALIAR TRABALHO; SEM BASE PARA DEFINIR DIAS',orientacoes:'ORIENTAÇÕES SUGERIDAS',encaminhamento:'',exames:'',pendencias:'ALERGIAS; IDADE; PROFISSÃO'};
test('pacote único usa esquema estruturado sem gerar solicitação adicional',()=>{const s=bundleJsonSchema();assert.equal(s.additionalProperties,false);assert.deepEqual(s.required,BUNDLE_FIELDS);assert.ok(BUNDLE_MAX_OUTPUT_TOKENS<=4200);});
test('regras do pacote distinguem histórico de sugestões',()=>{const p=formatClinicalBundlePrompt({caps:true});assert.match(p,/saída PRINCIPAL/i);assert.match(p,/possibilidades farmacológicas/i);assert.match(p,/estimativa provisória/i);assert.match(p,/NÃO forneça dose/i);assert.match(p,/MAIÚSCULAS/);});
test('pacote com textos e vazios é aceito; mantém cada documento separado',()=>{const b={status:'completed',output_text:JSON.stringify(data)};const r=validateClinicalBundle(b);assert.equal(r.ok,true);assert.match(r.text,/HDA: TRAUMA/);assert.match(r.documents.fisioterapia,/FISIOTERAPIA/);assert.match(r.documents.hipoteses,/HIPÓTESE/);assert.match(r.documents.tratamento,/MEDIDAS CONSERVADORAS/);assert.equal(r.documents.encaminhamento,'');assert.match(r.pendencias,/ALERGIAS/);});
test('resposta incompleta e formato fora do esquema são rejeitados',()=>{assert.equal(validateClinicalBundle({status:'incomplete',output_text:JSON.stringify(data)}).ok,false);assert.equal(validateClinicalBundle({status:'completed',output_text:'TEXTO SOLTO'}).ok,false);const {laudo,...missing}=data;assert.equal(validateClinicalBundle({status:'completed',output_text:JSON.stringify(missing)}).ok,false);});
test('sem seções da evolução o pacote não substitui texto anterior',()=>{assert.equal(validateClinicalBundle({status:'completed',output_text:JSON.stringify({...data,evolucao:'relato sem seções'})}).ok,false);});
